# Обновление проекта до платформы «Антракт».
# Запускать из папки проекта (где лежит файл artisan):
#   powershell -ExecutionPolicy Bypass -File .\update-antrakt.ps1
$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'artisan')) {
    Write-Host 'Запустите скрипт из папки проекта, где лежит файл artisan.' -ForegroundColor Red
    exit 1
}

function Write-ProjectFile([string]$Path, [string]$Base64) {
    $full = Join-Path (Get-Location).Path $Path
    $dir = Split-Path $full -Parent
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    $bytes = [Convert]::FromBase64String(($Base64 -replace '\s', ''))
    [IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  обновлён $Path"
}

Write-Host 'Записываю файлы...' -ForegroundColor Cyan

