Write-Host 'Удаляю устаревшие файлы...' -ForegroundColor Cyan
$old = @(
    'resources/views/events/database.blade.php',
    'public/js/events-db.js',
    'public/css/app.css',
    'tests/Unit/EventModelTest.php',
    'resources/views/welcome.blade.php'
)
foreach ($f in $old) { if (Test-Path $f) { Remove-Item $f -Force; Write-Host "  удалён $f" } }

if (-not (Test-Path '.env')) { Copy-Item '.env.example' '.env'; php artisan key:generate }
if (-not (Test-Path 'database/database.sqlite')) { New-Item 'database/database.sqlite' -ItemType File -Force | Out-Null }

Write-Host 'Очищаю кеш и пересоздаю базу...' -ForegroundColor Cyan
php artisan optimize:clear
php artisan migrate:fresh --seed --force

Write-Host ''
Write-Host 'Готово. Запустите сервер: php artisan serve' -ForegroundColor Green
Write-Host 'Откройте http://127.0.0.1:8000' -ForegroundColor Green
